import pandas as pd

class Solution:
    def average_selling_price(self, prices: pd.DataFrame, units_sold: pd.DataFrame) -> pd.DataFrame:
        stats = {}
        for _, p in prices.iterrows():
            rev = u = 0
            for _, s in units_sold[units_sold.product_id == p.product_id].iterrows():
                if p.start_date <= s.purchase_date <= p.end_date:
                    rev += int(s.units) * int(p.price)
                    u += int(s.units)
            cur = stats.setdefault(p.product_id, [0, 0])
            cur[0] += rev
            cur[1] += u
        rows = [(pid, round(r / n, 2) if n else 0.0) for pid, (r, n) in stats.items()]
        return pd.DataFrame(rows, columns=['product_id', 'average_price'])

