using namespace std;

struct PriceRow { int productId; string start, end; long long price; };
struct SaleRow { int productId; string date; long long units; };

class Solution {
public:
    vector<pair<int,double>> averageSellingPrice(vector<PriceRow>& prices, vector<SaleRow>& sales) {
        map<int, pair<long long,long long>> agg;
        for (auto& p : prices)
            for (auto& s : sales)
                if (p.productId == s.productId && p.start <= s.date && s.date <= p.end) {
                    auto& a = agg[p.productId];
                    a.first += s.units * p.price;
                    a.second += s.units;
                }
        vector<pair<int,double>> res;
        for (auto& [pid, a] : agg)
            res.push_back({pid, a.second ? round(a.first * 100.0 / a.second) / 100.0 : 0.0});
        return res;
    }
};

