import java.util.*;

class Solution {
    static class PriceRow { int productId; String start, end; long price;
        PriceRow(int p, String s, String e, long pr){productId=p;start=s;end=e;price=pr;} }
    static class SaleRow { int productId; String date; long units;
        SaleRow(int p, String d, long u){productId=p;date=d;units=u;} }

    public List<double[]> averageSellingPrice(List<PriceRow> prices, List<SaleRow> sales) {
        Map<Integer, long[]> agg = new TreeMap<>();
        for (PriceRow p : prices)
            for (SaleRow s : sales)
                if (p.productId == s.productId && p.start.compareTo(s.date) <= 0 && s.date.compareTo(p.end) <= 0) {
                    long[] a = agg.computeIfAbsent(p.productId, k -> new long[2]);
                    a[0] += s.units * p.price;
                    a[1] += s.units;
                }
        List<double[]> res = new ArrayList<>();
        for (var e : agg.entrySet()) {
            long[] a = e.getValue();
            double avg = a[1] == 0 ? 0.0 : Math.round(a[0] * 100.0 / a[1]) / 100.0;
            res.add(new double[]{e.getKey(), avg});
        }
        return res;
    }
}

