import pandas as pd
from collections import defaultdict

class Solution:
    def average_selling_price(self, prices: pd.DataFrame, units_sold: pd.DataFrame) -> pd.DataFrame:
        by_product = defaultdict(list)
        for _, s in units_sold.iterrows():
            by_product[s.product_id].append((s.purchase_date, int(s.units)))
        stats = defaultdict(lambda: [0, 0])
        for _, p in prices.iterrows():
            for date, units in by_product.get(p.product_id, []):
                if p.start_date <= date <= p.end_date:
                    stats[p.product_id][0] += units * int(p.price)
                    stats[p.product_id][1] += units
        rows = [(pid, round(v[0] / v[1], 2) if v[1] else 0.0) for pid, v in stats.items()]
        return pd.DataFrame(rows, columns=['product_id', 'average_price'])

